// The full presentation: a guided walkthrough of every tab and every subsection. It drives the real app (switches tabs, opens the sub-page being explained)
// while a side panel explains what it is, how to use it, and tips. Open it from Guide > "Full presentation", Ctrl+K, or the end of the quick tour.
(() => {
  const w = ms => new Promise(r => setTimeout(r, ms)); let idx = 0, el = null, token = 0;
  const esc2 = s => String(s == null ? '' : s).replace(/[&<>"]/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
  const rd = (k, d) => { try { return JSON.parse(ls.get(k, JSON.stringify(d))); } catch (e) { return d; } };

  /* ---------- navigation actions: 'tab:x', 'prep:x', 'tool:x', 'faith:x', 'click:selector', 'text:root|label', 'chess:label', 'play:id', 'music:label' ---------- */
  const clickText = (root, text) => { const r = document.querySelector(root); if (!r) return false; const els = [...r.querySelectorAll('button,.chip,div,span,a,li')].filter(e => e.offsetParent && e.children.length <= 3 && (e.textContent || '').replace(/\s+/g, ' ').trim().startsWith(text)); const e = els.sort((a, b) => a.textContent.length - b.textContent.length)[0]; if (e) { e.click(); return true; } return false; };
  async function openChess() {
    A.showTab('play'); await w(450);
    const inChess = () => [...document.querySelectorAll('#p-play button')].some(b => /Board settings/.test(b.textContent));
    if (!inChess()) { try { A.play.exit && A.play.exit(); } catch (e) { } await w(250); const leaf = [...document.querySelectorAll('#p-play *')].find(e => e.children.length === 0 && /♟️ Chess/.test(e.textContent)); if (leaf) (leaf.closest('[data-g]') || leaf.closest('button') || leaf.parentElement).click(); await w(1000); }
  }
  async function run(actions, my) {
    try { A.fav && A.fav.close(); } catch (e) { }
    for (const a of [].concat(actions || [])) {
      if (my !== undefined && my !== token) return;
      const i = a.indexOf(':'), k = a.slice(0, i), v = a.slice(i + 1);
      try {
        if (k === 'tab') { A.showTab(v); await w(500); }
        else if (k === 'prep') { A.showTab('health'); await w(600); const b = document.querySelector('#psub [data-s=' + v + ']'); if (b) b.click(); await w(500); }
        else if (k === 'studio') { A.studio.go(v); await w(800); }
        else if (k === 'tool') { A.showTab('tools'); await w(300); A.tools.go(v); await w(400); }
        else if (k === 'faith') { A.showTab('faith'); await w(900); const b = document.querySelector('#fasub [data-fs=' + v + ']'); if (b) b.click(); await w(400); }
        else if (k === 'play') { A.showTab('play'); await w(400); try { A.play.exit && A.play.exit(); } catch (e) { } await w(200); const b = document.querySelector('#p-play #' + v); if (b) b.click(); await w(400); }
        else if (k === 'chess') { await openChess(); if (v) { clickText('#p-play', v); await w(700); } }
        else if (k === 'music') { A.showTab('music'); await w(800); if (v) { clickText('#p-music', v); await w(500); } }
        else if (k === 'sky') { A.showTab('sky'); await w(600); A.sky.show(v); await w(1100); }
        else if (k === 'text') { const [r, t] = v.split('|'); clickText(r, t); await w(500); }
        else if (k === 'click') { const e = document.querySelector(v); if (e) e.click(); await w(400); }
      } catch (e) { }
    }
  }

  /* ---------- content ---------- */
  const S = (t, nav, what, how, tips, tryit) => ({ t, nav, what, how: how || [], tips: tips || [], tryit });
  const CH = [
    { id: 'start', icon: '🎬', t: 'Welcome', steps: [
      S('How this presentation works', ['tab:chat'], 'Moundshroud is your private assistant: everything runs on this PC with no account and no internet needed. This presentation visits every tab and every sub-page, switching the real app behind this panel so you can see what is being explained.',
        ['Press <b>Next</b> (or the right arrow key) to move on and <b>Back</b> to return.', 'Press <b>Contents</b> to jump straight to any tab or sub-page.', 'You can click around in the app while this panel is open. <b>Show me</b> takes you back to the page being explained.', 'Close it any time; it remembers where you were and offers to resume.'], ['The top bar of Moundshroud has the tabs; the magnifier (or <kbd>Ctrl</kbd>+<kbd>K</kbd>) searches everything; the gear holds settings; <kbd>F1</kbd> opens the written Guide.']),
      S('The top bar and Ctrl+K', ['tab:chat'], 'The row of tabs along the top is how you move around. The magnifier (also <kbd>Ctrl</kbd>+<kbd>K</kbd>) is one search box for your chats, notes, files and the offline library, and it also runs quick commands like "Open Library" or "My favorites".',
        ['Click a tab to switch to it. The order is Today, Chat, Search, Library, My Files, Notes, Study, Tools, Prepare, Entertainment, Music, Spiritual, Guide.', 'Press <kbd>Ctrl</kbd>+<kbd>K</kbd>, type a few letters, and press Enter on a result or command.', 'The model names at the top are the AI models installed; the small dot beside "Moundshroud" shows online or offline (Moundshroud works the same either way).'], ['Hotkeys that work anywhere in Windows (with the tray helper running): <kbd>Ctrl+Alt+A</kbd> opens Moundshroud, <kbd>Ctrl+Alt+Q</kbd> asks about selected text, <kbd>Ctrl+Alt+S</kbd> reads text from the screen, <kbd>Ctrl+Alt+N</kbd> quick note.']),
    ] },
    { id: 'home', icon: '🏠', t: 'Today', steps: [
      S('Today: your home page', ['tab:home'], 'The first tab is a home page that pulls together what matters right now. It only reads data already on this PC and stores nothing of its own.',
        ['The big box at the top asks Moundshroud anything and jumps to Chat.', 'Cards show the day of the church year and any feast, your next reminders, flashcards due and your study streak, your journal streak, where you left off (last library page, the Bible, favorites) and a tip.', 'A banner appears if you have not backed up for two weeks or the disk is nearly full.', 'The Go to tiles open every other tab.'], ['Press <b>Show me</b> on the tip card to jump into the presentation at that feature.']),
      S('📰 News', ['tab:news'], 'Headlines from more than 150 outlets (wire services, public broadcasters, papers and TV from left to right, outlets around the world, investigative newsrooms, beat specialists and official sources), grouped into events. Each event is ranked by how many independent outlets report it. It needs internet access switched on; the last edition stays readable offline.',
        ['Each event shows how well confirmed it is (single source, confirmed, widely reported, major story) and a coverage bar from left to right.', 'Open one to see every outlet’s own article, with opinion pieces kept separate, and press <b>✨ What we know</b> for a brief your local AI writes from those reports only, including where they disagree.', '<b>🎧 Briefing</b> reads the top stories aloud, <b>☆ Follow</b> collects later stories on the same subject, and <b>⚙ Sources</b> lets you switch outlets off, correct their lean or add your own feeds.'], ['Stories only one outlet has reported are under <b>Single-source</b>: treat them as unconfirmed.']),
    ] },
    { id: 'chat', icon: '💬', t: 'Chat', steps: [
      S('Chat: your AI assistant', ['tab:chat'], 'The main place to talk to the local AI. Everything is processed on this PC; nothing is sent anywhere. Answers stream in as they are written.',
        ['Type a question in the box at the bottom and press <kbd>Enter</kbd> (<kbd>Shift</kbd>+<kbd>Enter</kbd> adds a new line).', 'Press <b>Stop</b> to interrupt a long answer.', 'The example chips on a fresh chat show the kind of things to ask.'], ['<b>Think harder</b> (next to the model picker) lets the model reason first. It is slower but better for maths, logic and tricky questions.']),
      S('Models, files and libraries', ['tab:chat'], 'Under the box you choose how Moundshroud answers. The model picker switches between installed models. <b>Use my files</b> and <b>Use libraries</b> make Moundshroud look in your documents and the offline books first.',
        ['Tick <b>Use libraries</b> for factual questions; small source chips like <span class="src">[1]</span> appear under the answer.', 'Click a source chip to open the exact library page, or the PDF at the cited page.', 'Tick <b>Use my files</b> after adding folders in My Files to ask about your own documents.'], ['If the main model is busy or cannot start, a smaller one answers instead.']),
      S('Working with answers', ['tab:chat'], 'Hover any answer for its tools: <b>Copy</b>, <b>Listen</b> (read aloud), <b>Redo</b>, <b>Save to note</b> and <b>Make flashcards</b>. Hover your own message to <b>Edit</b> it and re-ask.',
        ['<b>Prompts</b> (beside Send) holds saved prompts such as reply, proofread and explain simply: type or paste text first, then pick one.', 'The clock button is your chat <b>History</b>; <b>New</b> or <kbd>Ctrl</kbd>+<kbd>N</kbd> starts a fresh chat.'], ['Edit your prompts in Prepare &rarr; Prompts. Use <kbd>{text}</kbd> where your text should go.']),
      S('Instant answers, no AI needed', ['tab:chat'], 'Some things are answered instantly by Moundshroud itself, even with the AI asleep: maths, percentages, unit conversions, time zones and date arithmetic. A small chip appears as you type.',
        ['Try <code>(12+8)*3</code>, <code>18% of 240</code>, <code>5 miles to km</code>, <code>3pm New York to London</code> or <code>days until december 25</code>.'], []),
      S('Ask Moundshroud to do things', ['tab:chat'], 'Moundshroud can operate its own app. Say what you want in plain English and it presses the buttons: it opens the right tab, builds a quiz, writes a document or sets a reminder. It only acts when asked, and anything that changes your PC shows a confirm box.',
        ['Try <i>make me a hard 10 question quiz on the French Revolution</i>, <i>make flashcards on the planets</i>, <i>create an 8 slide presentation on recycling</i>, <i>remind me to call Sam tomorrow at 9</i>, <i>open the translate tool</i>.'], ['This needs a model that supports tools (Qwen3.5 and llama3.1 do). With another model you just get an ordinary answer.']),
      S('Voice and attachments', ['tab:chat'], 'Talk to Moundshroud and show it things. <b>Talk</b> (top bar, or <kbd>Ctrl+Alt+V</kbd>) is a hands-free conversation; the microphone in the chat box types what you say; the paperclip attaches files.',
        ['Click <b>Talk</b>, speak, pause, and Moundshroud answers out loud then listens again. Say "stop" or press <kbd>Esc</kbd> to end.', 'Drag a PDF, Word, Excel, PowerPoint or text file onto Chat (or use the paperclip) then ask about it.', 'Paste or drag in a picture or screenshot and ask what it shows; Moundshroud switches to a model that can see.'], ['Speech recognition runs locally. If the microphone is blocked, allow it in Windows Settings &rarr; Privacy &rarr; Microphone.']),
    ] },
    { id: 'web', icon: '🌐', t: 'Browser: search', steps: [
      S('Search: ask anything, like a search engine', ['tab:web'], 'The Browser tab opens on a search page that searches every offline library on this PC (encyclopedia, Q&amp;A sites, guides, medical, survival, dictionary, books) plus your documents and notes, and writes a short answer with sources. Nothing leaves your computer.',
        ['Type any question or topic in the big box and press Enter. Suggestions and your recent searches appear as you type.', 'Use <b>💬 Ask in chat</b> if you would rather have a full conversation.'], ['It works for broad questions ("how do vaccines work"), names, error messages and how-tos.']),
      S('Reading results', ['tab:web'], 'A result page has a written <b>AI answer</b> with numbered citations, a knowledge panel for people, places and things, and ranked results below.',
        ['Click a citation number or a result to open the page in a tab right here. <b>◀</b> brings you back to your results. <b>Ask AI about this page</b> sends it to the assistant.', 'The tabs above the results narrow by kind: encyclopedia, Q&amp;A, guides, medical, code docs, books, your files and notes.'], ['The answer is only as good as the sources: open the cited page if it matters.']),
      S('Favorites and history', ['tab:web'], 'Keep what you find and clean up after yourself.',
        ['Press the ☆ beside any result (or in the reader) to favorite that page. <b>☆ Save search</b> saves the current query.', '<b>⭐ Favorites</b> opens your folders. <b>🧹 Clear history</b> wipes recent searches and opened pages; favorites are never touched.'], ['More on folders in the next chapter.']),
    ] },
    { id: 'lib', icon: '📚', t: 'Library', steps: [
      S('Library: classics and chess books', ['tab:lib'], 'The Library tab holds the books to read: <b>📖 Classics</b> (thousands of novels, plays, poems and story collections from Project Gutenberg, with covers), <b>♟ Chess books</b> (public-domain chess texts) and the <b>📖 Bible</b> reader (look up any verse, passage or chapter, or go to a random one). Encyclopedias, the dictionary and the medical and how-to books are in the 🌐 Browser tab.',
        ['Click a shelf to open it. Search by title or author, sort, jump by letter or view authors, and star favourites.', 'Click a book and it opens in a reader inside this tab. <b>← Shelves</b> goes back, <b>💬 Ask about this page</b> sends it to the assistant, and <b>Continue reading</b> on the Library home remembers what you opened.'], []),
    ] },
    { id: 'web2', icon: '🗂️', t: 'Browser: tabs and tools', steps: [
      S('Browser: a whole offline reference shelf', ['tab:web'], '108 offline books, about 72 GB: Wikipedia, dictionary, medical, survival and prep, tech help, cooking and DIY, Stack Exchange Q&amp;A, Wikivoyage, Wikiquote, developer docs and classic literature. Everything works with no internet.',
        ['Type in the big search box on the home page and press Enter. Once a page is open, the small address box under the tabs finds pages by title as you type.', 'The chips under the tab bar include <b>Random</b>, <b>Thesaurus</b> and <b>🎵 Rhymer</b>.'], ['Add more books under Prepare &rarr; Stock up while you have internet.']),
      S('The page toolbar', ['tab:web'], 'The bar under the search box works on whatever page is open.',
        ['<b>Back</b>, <b>Random</b>, <b>Thesaurus</b> and <b>🎵 Rhymer</b> (rhymes for songs).', '<b>Ask AI about this page</b>: summarize, explain simply, quiz me or make flashcards. <b>Read aloud</b> and <b>Save to note</b> too.', 'Select a word and press <kbd>Ctrl+Alt+D</kbd> anywhere to define it.'], []),
      S('Tabs, back and forward', ['tab:web'], 'The Browser is a full offline browser. Pages open in tabs, with back, forward, reload and home buttons, and your tabs and each tab\'s history come back the next time you open Moundshroud.',
        ['<b>◀ ▶</b> (or <kbd>Alt</kbd>+<kbd>Left</kbd> / <kbd>Right</kbd>, or the mouse back and forward buttons) move through the tab\'s history. Right-click ◀ or ▶ for the full list and jump anywhere.', '<b>＋</b> or <kbd>Ctrl</kbd>+<kbd>T</kbd> opens a new tab; <kbd>Ctrl</kbd>+<kbd>W</kbd> closes it; <kbd>Ctrl</kbd>+<kbd>Tab</kbd> switches. Hold <kbd>Ctrl</kbd> and click any link (or middle-click) to open it in a new tab. <b>Reopen closed tab</b> is in the ⋯ menu.', 'A result opens in the tab you searched from (use ◀ to get back to the results), or hold <kbd>Ctrl</kbd> and click to open it in a new tab.', 'The box doubles as an address bar: type a path starting with /wiki/ to go straight to a page, or words to search everything. <kbd>Ctrl</kbd>+<kbd>L</kbd> focuses it.'], ['Up to 10 tabs are kept; scroll position is remembered when you go back.']),
      S('Find, zoom, print and more', ['tab:web'], 'The ⋯ menu holds the everyday browser tools.',
        ['<b>Find in page</b> (<kbd>Ctrl</kbd>+<kbd>F</kbd>) counts matches and steps through them with the arrows or <kbd>Enter</kbd>.', '<b>Zoom</b> in, out or reset with <kbd>Ctrl</kbd> +, - and 0. Each tab remembers its own zoom.', '<b>Print or save as PDF</b> (<kbd>Ctrl</kbd>+<kbd>P</kbd>) prints the page; choose "Save as PDF" in the print window to keep a copy.', '<b>Copy link</b>, tab history, <b>All history</b> and <b>⭐ Favorites</b> are here too. The ☆ star next to it favorites the open page.'], []),
      S('⭐ Favorites and folders', ['tab:web', 'text:#p-lib|⭐ Favorites'], 'Star pages, whole libraries and searches, then sort them into folders you name.',
        ['<b>☆ Favorite</b> in the bar saves the open page; <b>☆ Save search</b> on the home page saves a search.', 'In the Favorites window: <b>＋ New folder</b>, rename (✎) or delete (🗑); move an item with its drop-down or drag it onto a folder; add a 📝 note; filter and sort.', '<b>History</b> lists pages you opened with Clear buttons. <b>Export</b> and <b>Import</b> back up your favorites.'], ['Deleting a folder keeps its favorites as Unsorted.']),
    ] },
    { id: 'files', icon: '🗂️', t: 'My Files', steps: [
      S('My Files: ask your own documents', ['tab:files'], 'Point Moundshroud at folders (Documents, school, a project) and then ask questions about what is inside. It reads PDF, Word, PowerPoint, Excel, OpenDocument, RTF, text, Markdown and web pages. Your files are never copied or changed.',
        ['Click <b>+ Add folder</b> and choose a folder. The first scan can take a while; later scans only look at changes.', 'Use the search box to find text across them. Click a result; PDFs open at the right page.', 'In Chat, tick <b>Use my files</b> and ask, for example, "What did the lease say about pets?". The answer cites file names and pages.'], ['<b>Re-scan now</b> picks up new files straight away. Remove a folder any time.']),
    ] },
    { id: 'notes', icon: '📝', t: 'Notes', steps: [
      S('Notes', ['tab:notes'], 'Plain text and Markdown notes saved as normal files in Documents\\Assistant Notes. They sync with OneDrive if your Documents do and open in any editor.',
        ['Press <b>+</b> for a new note and just type; it saves as you go.', '<b>Preview</b> shows the Markdown formatted. <b>Ask AI</b> summarizes or improves the note. <b>Flashcards</b> turns it into study cards. <b>Listen</b> reads it aloud.', 'Notes are part of search, so Moundshroud can use them when you ask questions.'], ['<kbd>Ctrl+Alt+N</kbd> anywhere drops a quick thought into a note called Quick Inbox.']),
    ] },
    { id: 'study', icon: '🎓', t: 'Study', steps: [
      S('Study: decks, quizzes, guides', ['tab:study'], 'Learn anything with spaced repetition, quizzes and study guides written by the AI.',
        ['<b>Make flashcards</b> from pasted text, a note, a chat answer or a library page. <b>Empty deck</b> makes a blank one to fill by hand; <b>Import</b> reads Quizlet-style tab-separated text.', '<b>Review due cards</b> shows what is ready today and keeps your day streak.'], []),
      S('Study modes', ['tab:study'], 'Open a deck and choose a mode.',
        ['<b>Flashcards</b> (Again / Hard / Good / Easy), <b>Learn</b> (multiple choice then typing), <b>Test</b> (graded with a review of misses), <b>Match</b> (beat the clock), <b>Write</b> and <b>Spell</b> (listen, then type).', 'Keys: <kbd>Space</kbd> flips; <kbd>1</kbd> to <kbd>4</kbd> answer or grade.'], ['Each card has four mastery dots; the deck bar shows how much you know.']),
      S('Quizzes and study guides', ['tab:study'], '<b>✨ New quiz</b> writes a quiz from a topic, pasted text, a note, a deck or a file, with instant feedback. <b>📘 Study guide</b> writes a guide, summary, cheat sheet, simple explanation or practice problems.',
        ['Pick a source, the number of questions, the level and the types (multiple choice, true/false, fill in the blank, short answer). Takes about 20 to 40 seconds.', 'After a quiz: a score, a review, <b>Retry the missed</b> and <b>Make flashcards from missed</b>.'], ['Tick "Add offline library notes" for specific topics like a person or event.']),
    ] },
    { id: 'lang', icon: '🌍', t: 'Languages', steps: [
      S('Languages: from first word to conversation', ['tab:lang'], 'A full course in <b>Spanish, French, German, Italian or Portuguese</b>, designed to take a complete beginner to comfortable conversation in about six months of daily practice. Everything runs on this PC; the only optional extra is a voice for your language so you can hear the words.',
        ['Pick a language and a pace: <b>Relaxed</b> (8 new words a day), <b>Steady</b> (12) or <b>Hero path</b> (20 a day, 6 days a week, about 6 months to roughly 3,000 words). You can change it any time.', 'Already know some? Choose <b>I know some: test my level</b> and the course starts where you are.', 'Each language keeps its own progress, XP and streak, so you can learn more than one.'], ['If you hear nothing, add a voice for the language in Windows Settings &rarr; Time &amp; language &rarr; Speech.']),
      S('The daily lesson', ['tab:lang'], 'Each lesson teaches new words inside real example sentences made only of words you already know, so you are never lost. It takes about 10 to 20 minutes.',
        ['New words come in small groups with the sentence, the translation and the spoken word.', 'Then you practise: multiple choice, <b>tap the words to build the sentence</b>, listen and choose, listen and type, fill in the blank and match pairs. Mistakes come back a few questions later.', 'You earn XP, build combos and keep a daily streak. Finish the day\'s goal to protect it.'], ['The accent buttons under typing boxes insert characters like ñ, é and ü.']),
      S('Review, checkpoints and milestones', ['tab:lang'], 'Spaced repetition brings every word and sentence back just before you would forget it.',
        ['<b>Review now</b> shows what is due. A short review each day matters more than a long one once a week.', 'After every five lessons a <b>weekly checkpoint</b> quizzes that week\'s words.', '<b>Milestone tests</b> unlock at 600, 1,200, 2,000 and 2,800 words (A1, A2, B1, B2). Pass with 75% to earn a printable certificate.'], []),
      S('Talk, Stories and Grammar', ['tab:lang', 'text:#p-lang|💬 Talk'], 'Practice for real with the local AI.',
        ['<b>💬 Talk</b>: choose a situation (café, directions, hotel, doctor...). The AI speaks simple language at your level, you can listen to it or translate any line, and it adds a ✏️ correction when you slip.', '<b>📖 Stories</b>: a fresh short story each time at your level. Tap a word you know for its meaning, listen, or translate.', '<b>💡 Grammar</b>: short, practical tips that unlock as you progress, each with a button to ask for more examples.', '<b>📚 My sentences</b> is a searchable phrasebook of everything you have learned, and <b>🔊 Sounds</b> is the pronunciation guide.'], ['Meanings are matched automatically from the example sentences, so trust the sentence translation first.']),
    ] },
    { id: 'studio', icon: '🎨', t: 'Studio', steps: [
      S('Studio: make art and music', ['tab:studio'], 'A workshop for making things: pixel art, drawing, generative art and music, plus the Teach me course builder. Everything runs on this PC.', [], []),
      S('🎨 Pixel art', ['tab:studio', 'text:#p-studio|🎨 Pixel art'], 'Draw sprites and animations one square at a time.',
        ['Pick a tool on the left (pencil, eraser, fill, line, rectangle, circle, picker, shift), a colour or palette, and draw. Right-click a pixel to pick its colour. Mirror drawing makes symmetrical art quickly.', 'Press <b>＋</b> under Frames to add an animation frame; <b>Play</b> shows it, onion skin shows the previous frame faintly.', 'Export a PNG, a sprite sheet or an animated GIF. <b>Pixelate a picture</b> converts a photo. Press <b>💾 Save</b> to keep it in the gallery.'], []),
      S('🖌️ Sketchpad and 🌀 Generative art', ['tab:studio', 'text:#p-studio|🖌️ Sketchpad'], 'Freehand drawing and seed-based generated patterns.',
        ['Sketchpad: pick pen, marker, spray, eraser or rainbow, tick <b>Symmetry</b> for mandala drawing, then save or download.', 'Generative art: choose a pattern and palette, then <b>🎲 New seed</b> for another picture. Type a seed to return to one you liked.'], []),
      S('🎹 Music studio', ['tab:studio', 'text:#p-studio|🎹 Music studio'], 'Compose a song from drums, bass and lead.',
        ['Click cells on the grid: Drums, Bass and Lead tabs. Bass and Lead use the scale you choose, so notes always fit. Try <b>🎲 Surprise me</b> for a starting idea.', 'Fill patterns A to D and type an order such as <b>AABA</b> to build a whole song. <b>▶ Play</b>, loop it, or play the keyboard live.', '<b>⬇ WAV</b> saves the audio; <b>➕ Add to My songs</b> puts it in the Music tab.'], ['Your speakers matter: the sounds are synthesized, so they are simple by design.']),
      S('🧑‍🎓 Teach me', ['tab:teach'], 'Say what you want to learn and for how long; Moundshroud drafts a day-by-day course.',
        ['Enter a topic, a length (7, 14 or 30 days), your level and minutes a day, then <b>Build my course</b>.', 'Open a day and the lesson is written for you, using facts from your offline libraries when they match. Then <b>Quiz me</b> (4 questions), <b>Make flashcards</b>, <b>Save as a note</b>, <b>Listen</b> or ask a follow-up in Chat.', 'Mark days complete to track progress. Courses are saved on this PC.'], ['Plans from small models can be uneven; a clear, narrow topic works best.']),
      S('Talk to your buddy', ['tab:home', 'click:#cmp .cb'], 'Click the animated character in the bottom-left corner and a small chat opens. Type or press the microphone.', ['Ask it to <b>play a song</b> ("play something by Bach", "play chill music"), <b>open a tab</b>, <b>analyze this page</b>, or <b>review my last chess game</b> (it runs the chess engine over your game and explains the key moments).', 'It can also make quizzes, set reminders and save notes, like the main chat. The 🔊 button reads its answers aloud.'], ['It refuses to talk about rated games and will tease you if you try.']),
      S('Your companion', ['tab:home'], 'A small buddy in the bottom-left corner cheers when you finish a language lesson, win a chess game or finish a course day, greets you once a day and naps when you are away.', ['Click it to hear something nice, switch buddy (owl, fox, octopus, robot, dragon, sloth, penguin, cat) or hide it. Ctrl+K &rarr; "Show my companion" brings it back.'], []),
    ] },
    { id: 'tools', icon: '🧰', t: 'Tools', steps: [
      S('Tools: the toolbox', ['tab:tools'], 'A row of utilities across the top: Documents, System, Calculator, Converter, Reminders &amp; timers, Translate, Clipboard, Prompts, Code Breaker, Cyber Course, Cyber Lab, CyberChef, Journal and Storage. Click one to open it.', [], []),
      S('Documents', ['tool:docs'], 'Moundshroud writes real Word files, spreadsheets, PowerPoint decks and PDFs, and converts between formats using LibreOffice.',
        ['Describe the document, choose the type, and press create. A preview appears with <b>Open</b> and <b>Show folder</b> buttons. Files go to Documents\\Moundshroud Documents.', 'Tick "Base it on the last answer in Chat" to turn an answer into a file.'], ['If LibreOffice is not found, install it from libreoffice.org.']),
      S('System', ['tool:sys'], 'Live processor, memory, disk and battery, the biggest memory users and your latest health check.', ['Open it when the PC feels slow to see what is using memory.'], []),
      S('Calculator', ['tool:calc'], 'A real keypad you can tap or type on, with a live answer, auto-closing brackets, history and memory keys, plus tabs for conversions, tip and split, percentages, dates and a smart box.',
        ['Type or tap an expression; the answer updates live. <b>DEG</b> toggles degrees and <b>Scientific</b> reveals more functions. <b>Ans</b> reuses the last result.', 'The <b>Smart box</b> understands things like "15% tip on 84 split 3".'], []),
      S('Converter', ['tool:conv'], 'Converts files from one type to another inside Moundshroud (your files are never uploaded): images, data files, text, audio, ZIPs and Office documents.',
        ['Drop one or many files on the box, choose what to convert to, press <b>Convert</b>, then <b>Download</b>.', 'Images can be resized, rotated or merged into one PDF; Office files go through LibreOffice.'], ['Video, sound, archives and songs to MIDI are converted on this PC and saved in Moundshroud Documents.']),
      S('Reminders and timers', ['tool:rem'], 'Reminders that pop up on time even when the Moundshroud window is closed (while the tray helper runs), with Snooze and Dismiss. They can <b>repeat</b>.',
        ['Say it in Chat or type it here: "remind me in 20 minutes to check the oven", "timer 25 min", "remind me every day at 8am to take my pills", "every Monday and Thursday at 6pm", "on weekdays at 7:30", "every 2 weeks on Friday", "monthly on the 15th".', 'The <b>🔁 Repeat options</b> panel builds the same thing with menus: every day, weekdays, weekly on chosen days, monthly, yearly or every few hours, plus an end date or a number of times.', 'Each repeating reminder shows its next few times. <b>Skip next</b>, <b>Pause</b>, <b>Edit</b> or <b>Delete</b> it from the list.', 'Use <b>Test pop-up</b> to confirm the pop-up works.'], ['Upcoming repeats are written ahead for the next 45 days, so they still fire when Moundshroud is closed. Open Moundshroud now and then to top them up.']),
      S('Translate', ['tool:trans'], 'Private translation between about 30 languages, fully on this PC.', ['Choose the languages, paste text and translate. Use the speaker to hear it.'], []),
      S('Clipboard', ['tool:clip'], 'An optional history of things you copied, searchable with <kbd>Ctrl+Alt+C</kbd>. It is off until you turn it on, stays on this PC, skips password-like text and can be cleared any time.', [], []),
      S('Prompts', ['tool:prm'], 'Your saved prompts for the Prompts button in Chat. Edit them or add your own, using <kbd>{text}</kbd> where the text you typed should go.', [], []),
      S('Code Breaker', ['tool:codes'], 'Cipher and puzzle solving tools. Paste mystery text and Moundshroud identifies and breaks Caesar, ROT13, Atbash, Vigenere, Base64, hex, binary, Morse and more, showing its working.',
        ['Paste the text, run the analysis, and read the ranked guesses. Use it for puzzles, geocaches and CTF practice.'], []),
      S('Learn to code', ['tab:cyber', 'click:#cysub [data-s=code]'], 'Cyber › 💻 Coding teaches programming in 12 languages, from beginner to advanced. Each lesson explains one idea and then you do it: Python and JavaScript run on the page and are checked, HTML shows a live preview, and the other languages use "what does it print", "fix the bug" and "fill the blank".', ['Pick a language, start with the first Beginner lesson, edit the code and press <b>Run and check</b>.', 'Points, a daily streak and finished lessons are kept; <b>Continue</b> opens the next lesson.'], ['Stuck? <b>💡 Hint</b> gives a nudge; <b>Show the answer</b> fills it in for fewer points.']),
      S('Wikibooks: free textbooks', ['tab:lib', 'click:#lywb'], 'Library › 📘 Wikibooks searches thousands of free community textbooks on this PC: programming, maths, science, languages, cooking and more.', ['Type a subject or tap one of the chips, then click a book to open it in the reader.'], []),
      S('Cyber Course', ['tool:course'], 'An 11-module course in security fundamentals with quizzes, a final exam and a certificate. Progress is saved.', ['Open a module, read the lesson, take its quiz, and finish the exam to earn the certificate.'], ['Practise on your own systems only.']),
      S('Cyber Lab', ['tool:cyber'], '16 security guides (ethics, networking, Linux, passwords, crypto, web attacks, phishing, forensics and more), a password-strength lab, and links to the hacker-style games.',
        ['Search or filter the guides, read one, then press <b>Practise</b> to jump to the matching game or <b>Ask Moundshroud about this</b>.'], ['Only test systems you own or have written permission to test.']),
      S('📓 Journal', ['tool:journal'], 'A private daily journal with a mood tracker, a prompt each day, a streak and a 15-week mood calendar. It is stored on this PC and Moundshroud only reads it when you press Reflect.',
        ['Pick how the day was, write (it saves as you type), and add one thing you are grateful for. Press <b>another</b> for a different prompt.', 'The calendar colours each day by mood; click a day to read or write it. The line chart shows the last 30 days.', '<b>✨ Reflect with Moundshroud</b> sends the last week of entries to the AI for a kind summary of themes. <b>Save as a note</b> and <b>Export journal</b> keep copies.'], ['It is not medical advice. If you are struggling, talk to someone you trust or a professional.']),
      S('💾 Storage', ['tool:storage'], 'Shows where your disk space goes (libraries, AI models, music, rollback snapshots, the window profile, documents) as a colour bar, with safe clean-up and a backup of the settings that live in the browser.',
        ['Read the bar and list; the drive gauge warns when free space is low.', '<b>Delete older ones</b> trims rollback snapshots to the newest 5, 10 or 20. <b>Clear the window\'s cache</b> frees browser cache and is rebuilt automatically.', '<b>Export settings and progress</b> saves favorites, Bible bookmarks and notes, chess profile, music playlists, journal and preferences to a file; <b>Import</b> restores them on a new PC.'], ['The first time after an update, restart Moundshroud so the new report can run.']),
      S('CyberChef', ['tool:chef'], 'The cyber swiss-army knife for encoding, decoding, hashing and converting data, completely offline.', ['Try <i>From Base64</i>, <i>ROT13</i>, <i>From Hex</i>, or the <i>Magic</i> operation on mystery text.'], []),
    ] },
    { id: 'prep', icon: '🛟', t: 'Prepare', steps: [
      S('Prepare: if the internet or power goes out', ['prep:ready'], 'Everything here works offline. It is general guidance, not professional advice: in an emergency call your local number first.', [], []),
      S('Ready', ['prep:ready'], 'A readiness score and checklist for Moundshroud and your household: AI model, library books, free disk space, recent backup, tray helper, contacts, supplies, stored water and binder.',
        ['Read the checks; use <b>Fix</b> buttons where offered. <b>Run test</b> tries every part of Moundshroud and confirms it makes no outside network requests.'], []),
      S('First aid', ['prep:aid'], 'Quick built-in steps for CPR, choking, bleeding, burns, stroke, heart attack, allergic reaction, hypothermia, heat stroke, fractures and shock, plus emergency-medicine articles and "ask the medical library".', ['Pick a topic and follow the numbered steps.'], []),
      S('Plans', ['prep:plans'], 'Step-by-step cards for power outage, no safe water, storm, flood, earthquake, wildfire, evacuation, winter storm, extreme heat, long outage, phones down, carbon monoxide, food safety and chemical release.',
        ['Each card has Right now, Next hours and days, a tick-list to prepare ahead and a Never list, with buttons to ask Moundshroud or search the survival library.'], []),
      S('Supplies', ['prep:supplies'], 'Tell Moundshroud your household (adults, children, pets, days, climate) and it works out water, food and power needs and keeps a checklist of about 60 items.',
        ['Fill in the household, tick items you have, add expiry dates and press <b>set expiry reminders</b>.'], []),
      S('People', ['prep:people'], 'Emergency and medical cards for each person, a contacts directory (import .vcf or .csv), meeting places, an out-of-area contact and utility shut-offs. <kbd>Ctrl+Alt+E</kbd> opens this page from anywhere.', ['Make a wallet-card PDF for each person.'], []),
      S('Signals', ['prep:signals'], 'Morse code with sound or a flashing screen, the phonetic alphabet, radio frequencies (FRS/GMRS, CB, NOAA, marine, aviation, amateur), distress and ground-to-air signals and emergency phrases in 12 languages.', [], []),
      S('Sky', ['tab:sky'], 'Sunrise, sunset, daylight and moon phase for any city or coordinates (worked out on this PC), ways to find direction without a compass and a coordinate converter.', [], []),
      S('✍️ Writing coach', ['studio:writing'], 'Paste an email, essay or post and improve it.',
        ['Pick <b>Make it clearer</b>, <b>Fix grammar only</b>, <b>Shorter</b>, <b>More formal</b>, <b>Friendlier</b>, <b>More persuasive</b> or <b>Plain language</b>. The result streams in with Copy, Save as note and <b>Use this instead</b>.', '<b>Full feedback report</b> gives strengths, problems with quotes and fixes, tone, structure and a score.', 'Live word count, reading time, reading ease and grade level appear under the box.'], []),
      S('🎤 Practice', ['studio:practice'], 'Rehearse job interviews and hard conversations with an AI partner.',
        ['Choose a job interview, debate, hard conversation, press questions, negotiation or Q&amp;A after a talk, and describe the situation.', 'Answer the questions; tick <b>Read aloud</b> to hear them. Press <b>Get feedback</b> for a score, what worked, what to improve and a stronger version of your weakest answer.'], []),
      S('Stock up', ['prep:stock'], 'Everything Moundshroud can download, in one place: offline libraries, AI models (from a list or any model by name), natural voices in 36 languages, the voice-typing model, the chess engine, the picture and music makers, CyberChef, the library engine and the music collections.', ['<b>Everything on this PC</b> lists what is already here, grouped, with sizes and the folder it is in.', '<b>🗑 Remove</b> on anything frees its space. You are warned first: it says what stops working and whether it can be downloaded again, and big or essential items need a tick to confirm.', 'Downloads keep going in the background and appear where they belong when finished.'], ['Check free disk space at the top before starting large downloads.']),
      S('🗺️ App map', ['tab:map'], 'The whole of Moundshroud laid out in one tab: every tab and the sections inside it, a reference sheet for setting up and doing everything, all the shortcuts and settings, where your data is kept and how big it is, everything downloaded, every outside connection, the helper programs and whether they are running, every code file with what it does, and every server address.', ['The <b>Reference sheet</b> is the quickest “how do I…”: one line per task with where to find it, the shortcut and a link to the Guide. 🖨 prints it.', 'The search box at the top left searches every section at once.', 'Most of it is read live from the app, so it is always up to date.'], ['Open tabs and settings straight from the map with the Open › buttons.']),
      S('Recipes', ['tab:kitchen'], '8,238 recipes from 16 public-domain cookbooks, stored on this PC.',
        ['Search by name, or type what is in your pantry. Filter by kind or cookbook, save favourites, print, or press a button to have Moundshroud modernize, convert or scale a recipe.'], ['Check old canning and meat instructions against modern guidance.']),
      S('Binder', ['prep:binder'], 'One printable PDF (or Word file) with contacts, medical cards, meeting places, supplies, plans, radio frequencies, signals and first aid.', ['Press build, then print one for your go-bag.'], []),
    ] },
    { id: 'play', icon: '🎭', t: 'Entertainment', steps: [
      S('Entertainment: games, stories and calm', ['tab:play'], 'Everything works offline. A row of pages across the top: Arcade, Cyber games, Sounds, Storyteller, Trivia, Fun with Moundshroud and Ambience. Press <kbd>Esc</kbd> to leave a game.', [], []),
      S('Arcade', ['play:arcade'], 'Thirty classic games with saved high scores: 2048, Snake, Memory, Connect Four, Breakout, Minesweeper, Sudoku, Word Guess, Tetris, Chess and more, plus <b>🕯️ Middle Watch</b>, an original pixel-art fantasy adventure in four chapters with saves (arrow keys or WASD, Z to talk, X or Esc for its menu).', ['Click a card to start. Each game has its own sounds and (optionally) music, and a 🔊 / 🎵 button at the top.'], []),
      S('Cyber games', ['play:cyber'], 'Six hacker-style games in a safe sandbox: Cipher Breaker, Terminal Hacker, SQL Injection Dojo, Phish Spotter, Net Ninja and Log Detective.', ['Pair them with the Cyber Lab guides in Tools.'], []),
      S('🎲 Tabletop', ['tab:play', 'click:#plsub [data-s=tabletop]'], 'Tools for game masters and players of tabletop role-playing games.',
        ['<b>Dice</b>: any die, modifiers, advantage and disadvantage, and expressions like <i>4d6kh3+2</i>, with a history.', '<b>Characters</b>: saved sheets with ability modifiers, one-click checks, 4d6-drop-lowest, HP and an AI backstory.', '<b>Initiative</b> tracker, <b>Generators</b> (names, NPCs, taverns, hooks, loot, encounters) and a <b>Dungeon map</b> generator with PNG export.'], []),
      S('🕳️ Depths', ['tab:play', 'click:#plsub [data-s=arcade]', 'click:#p-play [data-g=depths]'], 'A roguelike: pick Warrior, Rogue or Mage and descend procedurally generated floors. Arrow keys move and attack, 1-9 use items, > takes the stairs. Slay the Dragon on floor 10 or go deeper. One life, but your run autosaves.', [], []),
      S('🚀 Star Trader', ['tab:play', 'click:#plsub [data-s=arcade]', 'click:#p-play [data-g=trader]'], 'Buy low and sell high across twelve star systems. Watch fuel and hull, beat or flee pirates, buy upgrades, and aim for 250,000 credits. Autosaves.', [], []),
      S('🏰 Bastion', ['tab:play', 'click:#plsub [data-s=arcade]', 'click:#p-play [data-g=bastion]'], 'Tower defense: build archers, cannons, frost and Tesla towers beside the road, upgrade them, and hold out against growing waves and a boss every ten. Space starts a wave.', [], []),
      S('🏛️ Imperium: a life in Rome', ['tab:play'], 'A role-playing game set in the last years of the Republic, with little pixel-art Romans and its own orchestral score. Walk the city, talk to any Roman in the street through the local AI (they remember you and give you jobs), draft laws and fight for them in the Senate, and lead your legions in real-time battles with you on the field as the general.', ['Two stories: a career of your own in the year of Catilina (63 BC), or the life of Julius Caesar from 100 BC to the Ides of March.', 'Each chapter sends you around the city first and asks its hard question at the end. Rise from Tiro to Princeps.'], ['Look for it under Adventure in the Entertainment hub.']),
      S('⚪ Go 9×9, ⚫ Gomoku and 🥣 Mancala', ['tab:play', 'click:#plsub [data-s=arcade]', 'click:#p-play [data-g=go]'], 'Classic board games against the computer. In Go you play Black and the computer plays White (6.5 komi). Gomoku is five in a row; Mancala is Kalah with extra turns and captures.', [], []),
      S('🂡 Solitaire, 🃏 Blackjack and ♠️ Texas Hold\'em', ['tab:play', 'click:#plsub [data-s=arcade]', 'click:#p-play [data-g=solitaire]'], 'Card games with play money only.', ['<b>Solitaire</b>: click a card then a pile to move it, click the stock to draw, double-click to send a card to a foundation. There is an undo button and a Draw 3 option.', '<b>Blackjack</b>: pick a bet and Deal. Hit, Stand or Double. Blackjack pays 3:2 and your bankroll is saved.', '<b>Texas Hold\'em</b>: pick 1 to 5 opponents with different styles (Rock, Bluffer, Mathematician, Bully...), then play no-limit with a raise slider, half-pot, pot and all-in. Chat with the whole table: type a name to ask someone directly. The Card size setting makes everything bigger.'], []),
      S('Sounds', ['play:sounds'], 'Turn game sounds and theme music on or off, set volumes and hear every sound. By default games play classical piano; Chess plays Mozart.', ['Pick a game card to preview its sound; the Theme songs section has a music picker and Next piece.'], []),
      S('Storyteller', ['play:story'], 'An AI-run adventure. Pick a genre, then choose what happens next or type your own move. Your story is saved so you can continue later.', [], []),
      S('Trivia', ['play:trivia'], 'Moundshroud writes a fresh quiz on any topic you choose.', [], []),
      S('Fun with Moundshroud', ['play:fun'], 'Jokes, riddles, 20 Questions, characters and writing prompts in Chat, plus a random Wikipedia article from your library.', [], []),
      S('Ambience', ['play:calm'], 'Mix rain, ocean, wind, fireplace, summer night, brown noise and a calm pad. Set a sleep timer or start a Pomodoro (25 minutes focus, 5 minutes break). The sounds are generated on the spot.', [], []),
    ] },
    { id: 'chess', icon: '♟️', t: 'Chess', steps: [
      S('Chess: a full chess suite', ['chess:'], 'Chess is one game card in Arcade with sixteen tabs across the top: Play, Online, Tournament, Profile, Analysis, Coach, Courses, Puzzles, Openings, Famous games, Endgames, Mini-games, Trophies, Books, History and Board settings.', ['The next steps visit each tab.'], []),
      S('♟ Play: play Moundshroud and characters', ['chess:♟ Play'], 'Play the engine at any strength from 400 to 2400 Elo, as White, Black or random, with an optional clock. Every strength is a different character you can chat with.',
        ['Move the strength slider, pick your colour and clock, and press <b>New game</b>. Click or drag pieces. Hint, Undo, Flip, Resign and Offer draw are below the board.', '🎭 <b>Opponents</b> opens the character gallery and the learning bots. In the chat box you can talk, negotiate a draw or a take-back, and the opponent now reacts to the actual game: captures, forks, blunders, trades and who is winning. The <b>Chattiness</b> setting controls how often.', 'Click a move in the list to look back; <b>Analyze this game</b> sends it to Analysis.'], ['Finished games are saved automatically; copy or download them as PGN.']),
      S('🌐 Online simulator', ['chess:🌐 Online'], 'Feels like an online chess site but nothing goes on the internet: opponents are made up on your PC.',
        ['Choose <b>⭐ Rated</b> (counts toward your rating, no live coach) or <b>🧑‍🏫 Unrated</b> (practice, live coach on, and a 5 | 5 time control), a <b>variant</b> (Chess960, Three-check, King of the Hill) and a time control. See each side\'s captured pieces, use premoves (drop a piece while the opponent is thinking) and chat.'], ['Click several moves in a row to queue them; right-click the board to cancel them all.']),
      S('🧑‍🏫 Live coach', ['chess:♟ Play'], 'A coaching panel next to the board in Play, Online and Tournament games.', ['The bar shows who is better. After each move you get a grade (Best, Good, Inaccuracy, Mistake, Blunder) and, for weaker moves, the better one.', '<b>💡 Hint</b> draws the best move. <b>✨ Explain</b> asks the AI. <b>Blunder guard</b> (Play) asks before a move hangs a piece.', 'When a game ends you get an accuracy estimate and a button to review the whole game.'], ['Switch it off with the On box to play unaided.']),
      S('🏟 Tournament', ['chess:🏟 Tournament'], 'Run a whole simulated tournament: Swiss, round robin or knockout. You play your games for real; the others are decided by ratings.', ['Choose format, size, field strength and time control, then Play each round or Sim to the end.'], ['Leaving a game unfinished scores it as a loss.']),
      S('👤 Profile', ['chess:👤 Profile'], 'Your rating history, win/draw/loss record, move-quality ratings, openings you play and recent games.', [], []),
      S('🔬 Analysis', ['chess:🔬 Analysis'], 'Load a game (upload PGN, paste moves or a FEN, or pick a saved game) and press Analyze: accuracy for each side, a label on every move, an evaluation graph, key moments and the engine\'s top lines.', ['Move pieces on the board to try other ideas, then Back. <b>Turn my mistakes into puzzles</b> saves them.'], []),
      S('🔎 Review: arrows, lines and explanations', ['chess:🔬 Analysis'], 'After analysing a game, the Review tab explains every move and the board shows the engine\'s ideas as arrows.',
        ['Tick <b>Engine arrows</b> under the board for the top three moves with evaluations. <b>Played vs best</b> draws your weak move and the better one.', '<b>Right-drag</b> an arrow to ask the engine about that move: it grades it, shows what it prefers and draws the line as numbered arrows.', 'The <b>Engine</b> tab shows whole lines; hover to see them on the board, click to play them.', 'The <b>🔎 Review</b> tab: what each move does, why it works or is a problem, what else could be played, what changed, an AI explanation, and a story of the game with its turning points.'], ['Use ◀ key moment / key moment ▶ to jump between the important moves.']),
      S('🧑‍🏫 Coach', ['chess:🧑‍🏫 Coach'], 'The local AI explains moves and plans, and builds a training plan from your analysed games.', [], []),
      S('📘 Courses', ['chess:📘 Courses'], 'Seven courses with 61 lessons: you play the key moves, answer quizzes, and finish with endless puzzles on that theme.', [], []),
      S('🧩 Puzzles', ['chess:🧩 Puzzles'], 'Endless generated puzzles from one move to five. <b>Customize</b> sets move count, themes, difficulty, side, timer and more.', [], []),
      S('👥 Clubs and Friends', ['chess:👥 Clubs'], 'Friends and chess clubs, all simulated on this PC.', ['<b>Find players</b> to send friend requests (they usually accept), then <b>💬</b> to chat, <b>⚔</b> to challenge, <b>ⓘ</b> for a profile.', '<b>Clubs</b> lists 12 clubs to join. <b>👑 My clubs → Found a new club</b> lets you create your own and be its leader.', 'As leader use <b>✏️ Customize</b> (name, icon, colour, banner, motto, rules, welcome message, titles, who can join) and <b>⚙ Manage</b> (approve requests, invite friends). Members tab: make officers or remove people. Events tab: run a club tournament or a match against another club.'], []),
      S('⚡ Puzzle Rush and 🧭 Explorer', ['chess:⚡ Rush'], 'Chess.com-style extras.', ['<b>Puzzle Rush</b>: pick 3 minutes, 5 minutes or Survival. Solve puzzles on the board, three wrong moves end the run. They start easy and get harder.', '<b>Explorer</b> (next tab): play moves on the board and see which moves the opening book and famous games chose, plus your own win/draw/loss record from that position.'], []),
      S('📅 Daily games and Fog of War', ['chess:📅 Daily'], 'Correspondence chess: 1 to 14 days per move, clock resets after every move.', ['Pick days per move, a variant (Chess960, Three-check, King of the Hill, Fog of War, Atomic, Antichess, Racing Kings), your colour and a rating gap, then <b>Start game</b>. Games are saved and the opponent replies while you are away.', 'Use <b>⏩ Skip the wait</b> to fast-forward the simulated opponent. Fog of War hides everything your pieces cannot reach.', 'Online has a <b>Classical</b> row (30 and 60 minutes) and each variant keeps its own rating. A rated game shows the Elo you can win or lose in the chat.'], []),
      S('📖 Openings and 🏁 Endgames', ['chess:📖 Openings'], 'Study named openings with their ideas, and the key endgame positions every player should know.', ['Use the Endgames tab for practice against the engine from a given position.'], []),
      S('🏆 Famous games', ['chess:🏆 Famous games'], 'Ten great games to watch with comments or play as the winner.', [], []),
      S('🎮 Mini-games, 🏅 Trophies, 📚 Books, 🏛 History', ['chess:🎮 Mini-games'], 'Short chess challenges; trophies for milestones; public-domain chess books; and a history of chess with famous players and games.', [], []),
      S('⚙ Board settings', ['chess:⚙ Board settings'], 'Change board colours and pieces, coordinates (including outside the board), highlights, animation, move sounds and premoves.', [], []),
    ] },
    { id: 'music', icon: '🎼', t: 'Music', steps: [
      S('Music: a Spotify-style player', ['music:'], '518 free songs (about 31 hours, 21 genres) stored on this PC, plus your own music. It keeps playing while you use other tabs.', ['The sidebar has Home, Search, Browse, Your library, My music and About.'], []),
      S('🏠 Home and 🔎 Search', ['music:🏠 Home'], 'Home has Jump back in, ten daily mixes (Rock Out, Chill Vibes, Focus Flow and more), moods, genres and albums. Search finds songs by title, artist, genre, mood, instrument or tempo.', ['Try searching <i>rock</i>, <i>piano</i>, <i>relaxing</i> or <i>120 bpm</i>.'], []),
      S('Browse: songs, genres, moods, artists, albums', ['music:🎧 All songs'], 'Every page has Play and Shuffle.', ['Use Genres and Moods to explore, Artists and Albums to dig in.'], []),
      S('Your library: likes, playlists, history', ['music:❤️ Liked Songs'], 'Heart a song to like it. Make playlists with <b>New playlist</b> or the ⋯ menu on a song. Recently played and Most played fill in as you listen.', [], []),
      S('The player', ['tab:music'], 'Controls sit at the bottom: play/pause, previous, next, seek, volume, shuffle, repeat, the 📃 queue and a 🌙 sleep timer.', ['The ⋯ menu on a song has Play next, Add to queue, Track info and licence credit.', '<kbd>Space</kbd> plays or pauses when the Music tab is open.'], []),
      S('📁 My songs: import your own music', ['music:📁 My songs'], 'Add your own audio files or a whole folder (MP3, M4A, FLAC, OGG, OPUS, WAV). Moundshroud reads titles, artists and cover art, and your songs behave like any other song.', ['Press Add songs or Add a folder, or drag files onto the Music tab.', 'Songs are copied into Moundshroud\'s storage on this PC and never uploaded.'], []),
      S('🎙️ Record', ['music:🎙️ Record'], 'Record from your microphone, listen back, name it and save it to your library or download it.', ['Allow the microphone if asked.'], []),
      S('📷 Scan a chess position', ['play:chess'], 'Turn a picture of any chess position into a board: Games › Chess › 📷 Scan.', ['Drop, paste or choose a screenshot, a book diagram or a photo of a real board.', 'Fix any square with a click, then Analyse it or play it out.'], ['For a tilted photo, drag the four corners onto the board.']),
      S('♞ Lichess: real games online', ['play:chess'], 'Play real people (or the Lichess computer) on your own free Lichess account, on Moundshroud’s board: Games › Chess › ♞ Lichess.', ['Connect once with a token from lichess.org; the section links straight to the right page.', 'Rapid and Classical with strangers; Blitz and up with friends and the computer.'], ['While a game is on, every engine, hint and analysis in Moundshroud is locked, as Lichess requires.']),
      S('📻 Radio', ['tab:radio'], 'Live internet radio: news, talk, sports, music, weather, and the few police and fire scanner feeds that are public. It needs internet access switched on, and it keeps playing while you use other tabs.', ['Pick a kind along the top, or search by name. The country box narrows the list.', 'Press ▶ on a station to listen and ☆ to keep it in ⭐ Favorites.', '➕ Add a station takes any stream address you have, such as a local scanner feed.', 'The bar at the bottom shows the station and song, the volume, and the stop button.'], []),
      S('🎮 Game Studio (Godot)', ['tab:studio'], 'Studio › Game Studio turns a description into a real Godot 4 game, and everything stays inside Moundshroud.', ['▶ Play plays the game on the page, with ⛶ Full screen.', '🛠 Open in Godot opens the real Godot editor inside this window; 💾 Save to PC writes your changes back, and ← Back to Studio returns.'], []),
      S('🧰 Security Toolkit', ['tab:cyber'], 'Cyber › 🧰 Toolkit has 17 easy security tools, the kind on Kali Linux, running on this PC: DNS, WHOIS, a port scanner, a security-header grader, a certificate inspector, your local network, nearby Wi-Fi, hash tools, and a real packet capture with Wireshark. Each has a tutorial and a legal note; none attacks.', ['Press 💬 Ask the AI to explain this under any result.', 'The AI in Chat can run the tools too: “scan the ports on localhost”.', 'Only test systems you own or have written permission to test.'], []),
      S('📺 TV and YouTube', ['tab:tv'], 'Live TV channels and YouTube, watched inside Moundshroud. It needs internet access switched on.', ['📡 My channels groups your channels by category with real names and logos. Import from VLC brings in your VLC links.', '☰ Channel lists open with a button per category; ☆ keeps a channel.', '▶ YouTube searches YouTube and plays right in the tab.', '⛶ Full screen or the F key fills the screen; Esc comes back.', '🌐 More channels adds free channel lists by kind and country; typing in the box finds any of 11,000+ channels by name.', '⬇ on a YouTube video downloads it (whole, picture and sound apart, sound only or picture only); 📥 Downloads sorts them into folders.'], []),
      S('🖼️ Photos', ['tab:photos'], 'Your pictures by month, from your Pictures folder and any others you add. Files are only read, never moved or changed.', ['Press <b>✨ Describe my photos</b> and your local AI looks at each one, so you can search for “dog”, “beach 2024” or “birthday”.', 'Click a photo for the viewer: ← → to move, ★ to favourite, ▶ for a slideshow.'], ['OneDrive photos that are only in the cloud are not downloaded unless you open one.']),
      S('✉️ Mail', ['tab:mail'], 'Read your email from Gmail, Yahoo, iCloud, Proton Mail (through Bridge) and others, with scam warnings and tracking pictures blocked.', ['Connect with an <b>app password</b> from your account’s security settings.', '<b>✨ Inbox brief</b>, <b>✨ Summarise</b> and <b>✍ Help me reply</b> use the AI on this PC.'], ['Moundshroud never sends email: drafts go to your Drafts folder, to send from your phone or webmail.']),
      S('🔐 Passwords', ['tool:vault'], 'An encrypted password vault locked with one master password, with a generator and a check-up for weak and reused passwords.', ['Copied passwords are wiped from the clipboard after 30 seconds.', 'Import the passwords saved in your browser from ⚙ Vault › Import.'], ['If you forget the master password, nobody can open the vault. Write it down somewhere safe.']),
      S('ℹ️ Credits and licences', ['music:ℹ️ Credits'], 'Most music is Kevin MacLeod (CC BY 4.0) plus public-domain classical recordings. This page has the credit wording to use if you reuse a piece.', [], []),
    ] },
    { id: 'sky', icon: '🔭', t: 'Sky', steps: [
      S('Sky: the real sky from where you stand', ['sky:now'], 'Pick your city (or type coordinates) once and the Sky tab works out the sun, moon, planets and stars for your exact spot and time. All calculated on this PC; nothing is sent anywhere.', ['Press <b>Change place</b> at the top. Five pages: Tonight, Sky chart, Universe, Compass and Weather.'], []),
      S('🌙 Tonight', ['sky:now'], 'Sunrise, sunset, twilight and the time it gets fully dark; the Moon with its real phase, rise and set and the next full and new moon; and a table of which planets are up right now.', [], []),
      S('✨ Sky chart', ['sky:chart'], 'A live planetarium. Drag to look around, scroll to zoom, click any star, planet or deep-sky object for its distance, direction, and rise and set times. Search for anything, scrub time forward or back, and switch on constellations, grids, the Milky Way or night-vision red mode.', ['The sky colour follows the Sun, with real twilight glow.', 'Press <b>Look at it</b> to swing the view to an object, or <b>Follow it</b> to track it.'], []),
      S('🪐 Universe: Solar System, Stars in 3D, Scale', ['sky:uni'], 'The Solar System in 3D with every planet where it really is on any date, with a time-lapse. <b>Stars in 3D</b> shows bright stars at their true distances (try the Orion shape). <b>Scale of everything</b> flies outward from you to the edge of the observable universe.', ['Drag to rotate, scroll to zoom, click a planet or star.', 'Press <b>See it in your sky</b> in any info card to jump to the Sky chart.'], []),
      S('🧭 Compass', ['sky:compass'], 'A compass dial that shows where the Sun, Moon and planets are around you, finds any object or city by direction, converts true and magnetic north (you can measure your own declination from the Sun), and teaches finding direction without any instrument.', ['This PC has no compass sensor, so drag the dial to the way you are facing. A tablet or laptop with a sensor will turn it for you.'], []),
      S('🌦️ Weather (offline)', ['sky:weather'], 'Log a pressure reading (barometer, weather station or phone) plus wind and cloud, and Moundshroud forecasts the next 6 to 12 hours from the pressure trend, wind shifts and cloud types. It also has dew point, heat index, wind chill and lightning-distance calculators, a cloud guide, the Beaufort scale and storm safety.', ['Log a second reading about 3 hours later to get a trend.'], []),
    ] },
    { id: 'cal', icon: '📅', t: 'Calendar', steps: [
      S('Calendar: everything on one page', ['tab:cal'], 'Month, week and day views. Your events and reminders appear together with feasts, moon phases, equinoxes and solstices, and study cards due.', ['Click a day to see its details, sunrise and sunset, and the verse of the day.', 'Use the tick boxes to switch each kind of item on or off.', 'The Holidays box adds the big days of the year, including moving ones like Thanksgiving and Easter.'], []),
      S('+ Event and notifications', ['tab:cal'], 'Press <b>+ Event</b>: title, date, optional time, repeat and colour. Tick <b>Notify me</b> and Windows notifies you even when Moundshroud is closed.', [], []),
    ] },
    { id: 'kitchen', icon: '🍳', t: 'Kitchen', steps: [
      S('Kitchen: plan, stock, shop, cook', ['tab:kitchen'], 'A weekly <b>meal planner</b>, a <b>pantry</b>, a <b>shopping list</b> and 8,000 old recipes. It lives in the Life menu.', ['Press ＋ on a meal to add a recipe or your own dish.', '🎲 Surprise me fills the week\'s dinners from your pantry.'], []),
      S('Recipes that use what you have', ['tab:kitchen'], 'Add items to the pantry, then <b>What can I cook?</b> finds recipes. Open one to double it, add its ingredients to the shopping list, or have Moundshroud modernize it.', ['The old cookbooks are plain text, so check the shopping list Moundshroud builds.'], []),
    ] },
    { id: 'garden', icon: '🌱', t: 'Garden', steps: [
      S('Garden: what to plant now', ['tab:garden'], 'Moundshroud works out your frost dates from your place and lists what to start indoors, sow, plant out or sow for autumn today.', ['Change the frost dates if you know your local ones.', 'The plant guide shows friends and foes for each plant.'], []),
      S('Bed planner and harvest log', ['tab:garden'], 'In <b>My beds</b> click a square to plant. Green squares have a friendly neighbour, red squares a poor one. Log what you pick under <b>Harvest log</b>.', [], []),
    ] },
    { id: 'lab', icon: '🔬', t: 'Lab', steps: [
      S('Lab: periodic table and simulators', ['tab:lab'], 'Click any of the 118 elements for its configuration and a note. Then try projectiles (even on the Moon), a pendulum, orbits and circuit calculators.', ['Orbit speed 1.0 is a perfect circle; above 1.41 the planet escapes.'], []),
    ] },
    { id: 'timeline', icon: '🏛️', t: 'Timeline', steps: [
      S('Timeline: history you can zoom', ['tab:lib', 'click:#lytl'], 'Drag to move, scroll to zoom, click an event for a note and a link to the library. <b>Deep time</b> runs from the Big Bang to today.', ['Use the era buttons to jump, and the coloured chips to filter by kind.'], []),
    ] },
    { id: 'money', icon: '💰', t: 'Money', steps: [
      S('Money: a private budget', ['tab:money'], 'Add what you earn and spend, set monthly budgets, and track savings goals. Charts show where the money went. It is stored only on this PC.', ['Hide amounts blurs every figure.', 'CSV import and export are in the Tools page.'], []),
    ] },
    { id: 'faith', icon: '✝️', t: 'Spiritual', steps: [
      S('Spiritual: Bible, prayers and the Rosary', ['faith:today'], 'A tab of its own. It holds a full Catholic Bible in two public-domain translations, traditional prayers, a step-by-step Rosary, the liturgical calendar and devotional classics. Everything is stored on this PC.', ['The pages across the top: Today, Bible, Bible Expert, Learn, Prayers, Rosary, Library, Calendar, My notes and the devotional pages. The row scrolls sideways.'], []),
      S('🕊️ Today', ['faith:today'], 'The liturgical season and colour, any feast, a verse of the day, today\'s Rosary mysteries, your reading plan, coming feasts and a box to ask about the faith.', ['Press <b>☆ Save</b> under the verse to keep it in My notes, or switch on <b>Keep every daily verse automatically</b>.', 'Press <b>Pray the Rosary</b> or <b>Read the chapter</b> to jump in.'], []),
      S('✝️ Bible Expert', ['faith:expert'], 'Ask about Scripture, theology, the saints or Church history. It searches about 170 texts on this PC (the Church Fathers, Aquinas, the Catechism, the Catholic Encyclopedia, Vatican II, encyclicals, creeds, Orthodox and Protestant writers) and cites them as [1], [2]. The model does not quote from memory.', ['Open <b>Sources</b> under a reply to see the exact passages it was given.'], []),
      S('🎓 Learn the Bible', ['faith:learn'], 'Short hands-on lessons, all offline: the 73 books, the story of the Bible in 12 steps with the real passages, memorizing verses (they come back for review), and a quick quiz. You earn points and a daily streak.', ['Try <b>The story in 12 steps</b> for a first lesson.'], []),
      S('📖 Bible: two translations', ['faith:bible'], 'The <b>World English Bible</b> (modern easy English, Catholic edition) and the <b>Douay-Rheims</b> (traditional wording with Challoner\'s notes). Both are complete with the deuterocanon.',
        ['Choose the translation, then <b>Read in paragraphs</b> (flowing text, easiest to read) or <b>Verse by verse</b>. A+ and A− change text size.', 'Pick a book and chapter, or type a reference like <i>John 3:16</i> or any words to search.', 'Click a verse to copy, highlight, bookmark, add a note or have it explained. <b>📅 Reading plans</b> has the Gospels in 30 days, the New Testament in 90 and more.'], ['Switching translation keeps your place. The Psalms are numbered differently (Hebrew vs Greek/Latin) and Moundshroud converts the number for you.']),
      S('🙏 Prayers', ['faith:prayers'], '25 traditional prayers (Our Father, Hail Mary, creeds, Memorare, Angelus, grace before meals and more), searchable and copyable.', [], []),
      S('📿 Rosary', ['faith:rosary'], 'A guided Rosary: choose the Joyful, Sorrowful, Glorious or Luminous mysteries (today\'s is pre-selected), then step through each prayer with the scripture for each mystery and a bead tracker.', ['Press <b>Next</b> after each prayer.'], []),
      S('📚 Library', ['faith:library'], 'Ten public-domain devotional classics: the Imitation of Christ, Confessions, Story of a Soul, the Spiritual Exercises, Brother Lawrence, St. Benedict\'s Rule and the Baltimore Catechism.', ['Open a book, use the Contents menu to jump, and ask Moundshroud to explain a page.'], []),
      S('🗓️ Calendar', ['faith:cal'], 'The liturgical calendar for any month: seasons by colour, movable feasts such as Easter computed for the year, and fixed feasts and memorials.', ['Click a day for its details.'], ['This is the general Roman calendar; your diocese may differ.']),
      S('⭐ My notes', ['faith:mine'], 'Your bookmarks, highlighted verses and verse notes in one place, with a copy-all button.', [], []),
    ] },
    { id: 'guide', icon: '✨', t: 'Guide and settings', steps: [
      S('Guide', ['tab:guide'], 'The written manual: a searchable guide to every feature, a What\'s new list that grows with each update, the quick tour and this full presentation.', ['Press <kbd>F1</kbd> any time.'], []),
      S('Settings, themes and backup', ['tab:chat'], 'The gear opens Settings: <b>🎨 Customize appearance</b> (fonts, sizes, accent colour, tab animation), interface style, 10 colour themes, voice and speed, <b>Back up everything</b> (one zip) and restore.', ['Rolling back: before each change to Moundshroud a snapshot is saved; the Guide explains how to restore one.'], []),
      S('That is everything', ['tab:chat'], 'You have seen every tab. For detail on any feature use the Guide (<kbd>F1</kbd>) or just ask Moundshroud in Chat how to do something.', ['Reopen this presentation from Guide &rarr; Full presentation, or <kbd>Ctrl+K</kbd> and type "tutorial".'], []),
    ] },
  ];
  const FLAT = []; CH.forEach((c, ci) => c.steps.forEach((s, si) => FLAT.push({ c, ci, s, si })));

  /* ---------- the panel ---------- */
  const css = '#tutp{position:fixed;right:14px;top:60px;bottom:14px;width:min(430px,94vw);z-index:90;background:var(--panel);border:1px solid var(--line);border-radius:16px;box-shadow:0 20px 60px rgba(0,0,0,.55);display:flex;flex-direction:column;overflow:hidden}#tutp .th{padding:12px 14px 8px;border-bottom:1px solid var(--line)}#tutp .tb{flex:1;overflow:auto;padding:14px 16px;line-height:1.55}#tutp .tf{display:flex;gap:8px;padding:10px 12px;border-top:1px solid var(--line);align-items:center}#tutp h3{margin:0 0 6px;font-size:18px}#tutp .lab{font-size:11px;letter-spacing:.06em;text-transform:uppercase;color:var(--acc);font-weight:700;margin:14px 0 4px}#tutp ol,#tutp ul{margin:0;padding-left:20px}#tutp li{margin:4px 0}#tutp .toc{position:absolute;inset:0;background:var(--panel);z-index:2;overflow:auto;padding:12px 14px}#tutp .toc .ch{font-weight:700;margin:12px 0 4px;cursor:default}#tutp .toc .st{padding:5px 8px;border-radius:8px;cursor:pointer;font-size:14px}#tutp .toc .st:hover{background:var(--panel2)}#tutp .toc .st.on{background:var(--acc);color:var(--onacc,#fff)}';
  if (!document.getElementById('tutcss')) { const s = document.createElement('style'); s.id = 'tutcss'; s.textContent = css; document.head.appendChild(s); }
  
  function close() { if (el) { el.remove(); el = null; } document.removeEventListener('keydown', onkey, true); }
  function onkey(e) { if (!el || /INPUT|TEXTAREA|SELECT/.test((document.activeElement || {}).tagName || '')) return; if (e.key === 'ArrowRight') { e.preventDefault(); go(idx + 1); } else if (e.key === 'ArrowLeft') { e.preventDefault(); go(idx - 1); } else if (e.key === 'Escape') { e.stopPropagation(); close(); } }
  async function go(i) {
    if (i < 0) i = 0; if (i >= FLAT.length) { close(); ls.set('tut_done', '1'); A.showTab('chat'); A.toast('That was the whole tour. Press F1 for the Guide any time.', 3500); return; }
    idx = i; ls.set('tut_pos', String(i)); const my = ++token; const { c, ci, s, si } = FLAT[i];
    if (!el) { el = document.createElement('div'); el.id = 'tutp'; document.body.appendChild(el); el.onclick = onclick; document.addEventListener('keydown', onkey, true); }
    const total = FLAT.length;
    el.innerHTML = '<div class="th"><div class="row" style="align-items:center;gap:8px"><b style="font-size:13px">' + c.icon + ' ' + esc2(c.t) + ' <span class="mute" style="font-weight:400">· ' + (si + 1) + '/' + c.steps.length + '</span></b><span class="sp"></span><span class="small mute">' + (i + 1) + ' of ' + total + '</span><button class="ib" data-x="1" title="Close">✕</button></div><div class="bar" style="margin-top:8px"><i style="width:' + Math.round((i + 1) / total * 100) + '%"></i></div></div>' +
      '<div class="tb"><h3>' + esc2(s.t) + '</h3><div>' + s.what + '</div>' + (s.how.length ? '<div class="lab">How to use it</div><ol>' + s.how.map(h => '<li>' + h + '</li>').join('') + '</ol>' : '') + (s.tips.length ? '<div class="lab">Good to know</div><ul>' + s.tips.map(h => '<li>' + h + '</li>').join('') + '</ul>' : '') + '</div>' +
      '<div class="tf"><button class="ib" data-back="1"' + (i === 0 ? ' disabled' : '') + '>‹ Back</button><button class="ib" data-show="1" title="Go back to the page being explained">Show me</button><button class="ib" data-toc="1">Contents</button><span class="sp"></span><button class="pri" data-next="1">' + (i === total - 1 ? 'Finish' : 'Next ›') + '</button></div>';
    await run(s.nav, my);
  }
  function toc() {
    const t = document.createElement('div'); t.className = 'toc'; t.innerHTML = '<div class="row" style="align-items:center"><b>Contents</b><span class="sp"></span><button class="ib" data-tocx="1">Close</button></div>' + CH.map((c, ci) => '<div class="ch">' + c.icon + ' ' + esc2(c.t) + '</div>' + c.steps.map((s, si) => { const n = FLAT.findIndex(f => f.ci === ci && f.si === si); return '<div class="st' + (n === idx ? ' on' : '') + '" data-goto="' + n + '">' + esc2(s.t.replace(/<[^>]+>/g, '')) + '</div>'; }).join('')).join(''); el.appendChild(t);
    const on = t.querySelector('.on'); if (on) on.scrollIntoView({ block: 'center' });
  }
  function onclick(e) {
    const T = e.target, c = s => T.closest(s); let x;
    if (c('[data-x]')) { close(); return; } if (c('[data-next]')) { go(idx + 1); return; } if (c('[data-back]')) { go(idx - 1); return; }
    if (c('[data-show]')) { run(FLAT[idx].s.nav); return; } if (c('[data-toc]')) { toc(); return; } if (c('[data-tocx]')) { const t = el.querySelector('.toc'); if (t) t.remove(); return; }
    if ((x = c('[data-goto]'))) { go(+x.dataset.goto); return; }
  }
  function start(i) { try { A.closeDlg && A.closeDlg(); } catch (e) { } return go(i == null ? 0 : i); }
  function resume() { const p = +ls.get('tut_pos', '0') || 0; if (p > 0 && p < FLAT.length) { A.dlg('<div class="hd"><b>🎬 Full presentation</b></div><div class="bd"><div style="margin:4px 0 12px">You were at <b>' + esc2(FLAT[p].c.t + ': ' + FLAT[p].s.t.replace(/<[^>]+>/g, '')) + '</b>. Pick up there or start over?</div><div class="row"><button class="ib" id="tr0">Start over</button><span class="sp"></span><button class="pri" id="tr1">Resume</button></div></div>'); document.getElementById('tr0').onclick = () => start(0); document.getElementById('tr1').onclick = () => start(p); } else start(0); }
  A.tutorial = { find: txt => Math.max(0, FLAT.findIndex(f => f.s.t.replace(/<[^>]+>/g, '').toLowerCase().includes(String(txt).toLowerCase()))), start, resume, close, steps: () => FLAT.length, chapters: () => CH.map(c => c.t) };
})();
